-- Guard last active owner even when a privileged operator modifies tables
-- directly. Owner grants and memberships must never expire automatically.
create function public.staff_guard_owner_membership()
returns trigger language plpgsql security invoker set search_path = ''
as $function$
declare
  v_has_owner boolean;
  v_other_owners integer;
begin
  select exists (
    select 1 from public.staff_member_roles r
    join public.staff_role_presets p on p.id = r.role_preset_id
    where r.membership_id = old.id and p.role_key = 'owner'
  ) into v_has_owner;

  if not v_has_owner then
    if tg_op = 'DELETE' then return old; end if;
    return new;
  end if;

  perform pg_catalog.pg_advisory_xact_lock(202611, 2302);

  if tg_op = 'UPDATE' then
    if new.auth_user_id is distinct from old.auth_user_id then
      raise exception 'Owner identity cannot be reassigned'
        using errcode = '42501';
    end if;
    if new.status = 'active' then
      if new.expires_at is not null or new.member_type <> 'employee' then
        raise exception 'An active owner must be an unexpired employee'
          using errcode = '23514';
      end if;
      return new;
    end if;
  end if;

  select count(*) into v_other_owners
  from public.staff_memberships m
  join public.staff_member_roles r on r.membership_id = m.id
  join public.staff_role_presets p on p.id = r.role_preset_id
  where p.role_key = 'owner' and m.id <> old.id
    and m.status = 'active' and m.expires_at is null
    and m.member_type = 'employee' and r.expires_at is null;

  if v_other_owners < 1 then
    raise exception 'Cannot remove or deactivate the last active owner'
      using errcode = '23514';
  end if;

  if tg_op = 'DELETE' then return old; end if;
  return new;
end;
$function$;

create trigger staff_owner_membership_guard
  before update or delete on public.staff_memberships
  for each row execute function public.staff_guard_owner_membership();

create function public.staff_guard_owner_role()
returns trigger language plpgsql security invoker set search_path = ''
as $function$
declare
  v_old_is_owner boolean := false;
  v_new_is_owner boolean := false;
  v_other_owners integer;
begin
  if tg_op <> 'INSERT' then
    select exists(
      select 1 from public.staff_role_presets
      where id = old.role_preset_id and role_key = 'owner'
    ) into v_old_is_owner;
  end if;

  if tg_op <> 'DELETE' then
    select exists(
      select 1 from public.staff_role_presets
      where id = new.role_preset_id and role_key = 'owner'
    ) into v_new_is_owner;
  end if;

  if v_old_is_owner then
    if tg_op = 'DELETE' then
      v_old_is_owner := true;
    elsif tg_op = 'UPDATE' then
      v_old_is_owner := new.role_preset_id is distinct from old.role_preset_id
        or new.membership_id is distinct from old.membership_id;
    else
      v_old_is_owner := false;
    end if;
  end if;

  if v_old_is_owner then
    perform pg_catalog.pg_advisory_xact_lock(202611, 2302);
    select count(*) into v_other_owners
    from public.staff_memberships m
    join public.staff_member_roles r on r.membership_id = m.id
    join public.staff_role_presets p on p.id = r.role_preset_id
    where p.role_key = 'owner' and m.id <> old.membership_id
      and m.status = 'active' and m.expires_at is null
      and m.member_type = 'employee' and r.expires_at is null;
    if v_other_owners < 1 then
      raise exception 'Cannot revoke or move the last active owner role'
        using errcode = '23514';
    end if;
  end if;

  if v_new_is_owner then
    if new.expires_at is not null or not exists (
      select 1 from public.staff_memberships m
      where m.id = new.membership_id and m.status = 'active'
        and m.expires_at is null and m.member_type = 'employee'
    ) then
      raise exception 'Owner grants must belong to an active nonexpiring employee'
        using errcode = '23514';
    end if;
  end if;

  if tg_op = 'DELETE' then return old; end if;
  return new;
end;
$function$;

create trigger staff_owner_role_guard
  before insert or update or delete on public.staff_member_roles
  for each row execute function public.staff_guard_owner_role();

-- Built-in role identifiers must not be swapped to sidestep the owner
-- invariant. Display names may be revised in a later approved admin workflow.
create function public.staff_guard_builtin_role_preset()
returns trigger language plpgsql security invoker set search_path = ''
as $function$
begin
  if old.is_builtin = true then
    if tg_op = 'DELETE' then
      raise exception 'Built-in role presets cannot be deleted'
        using errcode = '42501';
    end if;
    if new.role_key is distinct from old.role_key or
       new.is_builtin is distinct from old.is_builtin then
      raise exception 'Built-in role identities are immutable'
        using errcode = '42501';
    end if;
  end if;
  if tg_op = 'DELETE' then return old; end if;
  return new;
end;
$function$;

create trigger staff_builtin_role_preset_guard
  before update or delete on public.staff_role_presets
  for each row execute function public.staff_guard_builtin_role_preset();

-- The audit hook runs in the caller's privileges (SECURITY INVOKER).
-- A normal staff mutation must originate from a valid active owner actor.
-- Manual initial owner bootstrap is intentionally a separately approved DBA
-- task: only the database owner can audit with a NULL actor.
create function public.staff_record_access_change()
returns trigger language plpgsql security invoker set search_path = ''
as $function$
declare
  v_actor uuid;
  v_request_id uuid;
  v_reason text;
  v_before jsonb;
  v_after jsonb;
  v_membership_id uuid;
begin
  v_actor := nullif(pg_catalog.current_setting('app.staff_actor_auth_id', true), '')::uuid;
  v_request_id := nullif(pg_catalog.current_setting('app.staff_request_id', true), '')::uuid;
  v_reason := nullif(pg_catalog.current_setting('app.staff_reason', true), '');
  if current_user <> 'postgres' then
    if v_actor is null or not exists(
      select 1 from public.staff_memberships m
      join public.staff_member_roles r on r.membership_id = m.id
      join public.staff_role_presets p on p.id = r.role_preset_id
      where m.auth_user_id = v_actor and m.status = 'active'
        and m.expires_at is null and m.member_type = 'employee'
        and p.role_key = 'owner' and r.expires_at is null
    ) then
      raise exception 'Staff mutation must be attributed to a current owner'
        using errcode = '42501';
    end if;
    if v_reason is null or length(pg_catalog.btrim(v_reason)) < 12 then
      raise exception 'Staff mutation requires a meaningful audit reason'
        using errcode = '22023';
    end if;
  end if;

  if tg_op <> 'INSERT' then v_before := pg_catalog.to_jsonb(old); end if;
  if tg_op <> 'DELETE' then v_after := pg_catalog.to_jsonb(new); end if;
  v_membership_id := nullif(coalesce(
    v_after->>'membership_id',v_before->>'membership_id',
    case when tg_table_name = 'staff_memberships'
      then coalesce(v_after->>'id',v_before->>'id')
    end
  ), '')::uuid;

  insert into public.staff_access_audit(
    actor_auth_user_id, subject_membership_id, action_key,
    before_state, after_state, reason, request_id
  ) values (
    v_actor, v_membership_id, tg_table_name || '.' || pg_catalog.lower(tg_op),
    v_before, v_after,
    coalesce(v_reason, 'Manually reviewed database operation'),
    v_request_id
  );
  return null;
end;
$function$;

create trigger staff_memberships_audit
  after insert or update or delete on public.staff_memberships
  for each row execute function public.staff_record_access_change();
create trigger staff_member_roles_audit
  after insert or update or delete on public.staff_member_roles
  for each row execute function public.staff_record_access_change();
create trigger staff_role_presets_audit
  after insert or update or delete on public.staff_role_presets
  for each row execute function public.staff_record_access_change();
create trigger staff_role_capabilities_audit
  after insert or update or delete on public.staff_role_capabilities
  for each row execute function public.staff_record_access_change();
create trigger staff_capability_overrides_audit
  after insert or update or delete on public.staff_capability_overrides
  for each row execute function public.staff_record_access_change();
create trigger staff_story_assignments_audit
  after insert or update or delete on public.staff_story_assignments
  for each row execute function public.staff_record_access_change();

-- Atomic mutation entry point. SECURITY INVOKER: no RLS bypass added.
-- Execution is ONLY for the trusted server-side service_role. The Next.js
-- adapter must verify auth.getUser() and derive p_actor_auth_user_id itself.
-- The function ALSO rechecks a current active owner directly in Postgres.
create function public.staff_apply_role_change(
  p_actor_auth_user_id uuid,
  p_target_membership_id uuid,
  p_operation text,
  p_role_key text,
  p_reason text,
  p_request_id uuid
)
returns uuid language plpgsql security invoker set search_path = ''
as $function$
declare
  v_target_auth_user_id uuid;
  v_role_id uuid;
  v_changed integer;
begin
  if p_actor_auth_user_id is null or p_target_membership_id is null or
     p_request_id is null or p_reason is null or
     length(pg_catalog.btrim(p_reason)) < 12 or length(p_reason) > 500 then
    raise exception 'Invalid or incomplete staff mutation request'
      using errcode = '22023';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(202611, 2302);

  if not exists (
    select 1 from public.staff_memberships m
    join public.staff_member_roles r on r.membership_id = m.id
    join public.staff_role_presets p on p.id = r.role_preset_id
    where m.auth_user_id = p_actor_auth_user_id
      and m.status = 'active' and m.expires_at is null
      and m.member_type = 'employee' and p.role_key = 'owner'
      and r.expires_at is null
  ) then
    raise exception 'Only a current owner can change staff access'
      using errcode = '42501';
  end if;

  select auth_user_id into v_target_auth_user_id
  from public.staff_memberships
  where id = p_target_membership_id for update;

  if not found then
    raise exception 'Target staff membership does not exist'
      using errcode = 'P0002';
  end if;

  if v_target_auth_user_id = p_actor_auth_user_id then
    raise exception 'Owners cannot change their own membership or roles'
      using errcode = '42501';
  end if;

  if p_operation in ('grant_role', 'revoke_role') then
    if p_role_key is null then
      raise exception 'A role key is required' using errcode = '22023';
    end if;
    select id into v_role_id from public.staff_role_presets
      where role_key = p_role_key and is_builtin = true;
    if v_role_id is null then
      raise exception 'Invalid role preset' using errcode = '22023';
    end if;
  elsif p_operation in ('suspend', 'reactivate', 'revoke_membership') then
    if p_role_key is not null then
      raise exception 'A role key is not valid for this operation'
        using errcode = '22023';
    end if;
  else
    raise exception 'Unsupported staff mutation action' using errcode = '22023';
  end if;

  perform pg_catalog.set_config('app.staff_actor_auth_id', p_actor_auth_user_id::text, true);
  perform pg_catalog.set_config('app.staff_request_id', p_request_id::text, true);
  perform pg_catalog.set_config('app.staff_reason', p_reason, true);

  if p_operation = 'grant_role' then
    insert into public.staff_member_roles(membership_id,role_preset_id,granted_by)
      values (p_target_membership_id,v_role_id,p_actor_auth_user_id)
      on conflict (membership_id,role_preset_id) do nothing;
    get diagnostics v_changed = row_count;
  elsif p_operation = 'revoke_role' then
    delete from public.staff_member_roles
      where membership_id = p_target_membership_id and role_preset_id = v_role_id;
    get diagnostics v_changed = row_count;
  elsif p_operation = 'suspend' then
    update public.staff_memberships
      set status = 'suspended', suspended_at = now(), updated_at = now()
      where id = p_target_membership_id and status = 'active';
    get diagnostics v_changed = row_count;
  elsif p_operation = 'reactivate' then
    update public.staff_memberships
      set status = 'active', activated_at = coalesce(activated_at,now()),
          suspended_at = null, updated_at = now()
      where id = p_target_membership_id and status = 'suspended'
        and (expires_at is null or expires_at > now());
    get diagnostics v_changed = row_count;
  elsif p_operation = 'revoke_membership' then
    update public.staff_memberships
      set status = 'revoked', revoked_at = now(), updated_at = now()
      where id = p_target_membership_id and status in ('active','suspended','invited');
    get diagnostics v_changed = row_count;
  end if;

  if v_changed <> 1 then
    raise exception 'No staff record was changed'
      using errcode = 'P0002';
  end if;
  return p_request_id;
end;
$function$;

-- Postgres grants EXECUTE to PUBLIC by default on new functions.
-- Explicitly remove the exposed RPC from public, anon and authenticated.
revoke all on function public.staff_apply_role_change(
  uuid,uuid,text,text,text,uuid
) from public, anon, authenticated;
grant execute on function public.staff_apply_role_change(
  uuid,uuid,text,text,text,uuid
) to service_role;

revoke all on function public.staff_guard_owner_membership() from public,anon,authenticated;
revoke all on function public.staff_guard_owner_role() from public,anon,authenticated;
revoke all on function public.staff_record_access_change() from public,anon,authenticated;
revoke all on function public.staff_guard_builtin_role_preset() from public,anon,authenticated;
grant execute on function public.staff_guard_owner_membership() to service_role;
grant execute on function public.staff_guard_owner_role() to service_role;
grant execute on function public.staff_record_access_change() to service_role;
grant execute on function public.staff_guard_builtin_role_preset() to service_role;

commit;
